@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Aadvent-of-code
@description Soothing pastel theme for Advent Of Code
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("adventofcode.com") {
  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    body {
      background: @base;
      color: @text;

      header h1 a,
      header h1 span {
        color: @green;
        text-shadow: 0 0 2px @green, 0 0 5px @green;
      }

      a {
        color: @green;
      }

      .star-count {
        color: @yellow;
      }

      .quiet {
        color: @subtext0;
        opacity: 1;
      }

      .share,
      .share:hover,
      input[type="submit"] {
        color: @green;
      }

      main {
        article {
          em {
            color: @text;
            text-shadow: 0 0 5px @text;
          }

          h2 {
            color: @text;
          }

          input[type="radio"]:checked ~ span,
          input[type="checkbox"]:checked ~ span {
            color: @text;
          }

          input[type="radio"] ~ span:hover,
          input[type="radio"] ~ span:focus,
          input[type="checkbox"]:hover ~ span,
          input[type="checkbox"]:focus ~ span {
            background-color: @crust;
          }
        }
        .supporter-badge {
          color: @yellow;
        }

        .supporter-badge:hover {
          color: @yellow;
          text-shadow: 0 0 5px @yellow;
        }

        .sponsor-badge {
          color: @blue;
        }

        .sponsor-badge:hover,
        .sponsor-badge:focus {
          color: @blue;
          text-shadow: 0 0 5px @blue;
        }

        .leaderboard-entry {
          .leaderboard-position {
            color: @subtext1;
          }
          .leaderboard-totalscore {
            color: @text;
          }
        }

        .leaderboard-daylinks-selected {
          color: @text;
          text-shadow: 0 0 5px @text;
        }

        .leaderboard-daylinks-selected:hover {
          color: @green;
        }

        .leaderboard-anon {
          opacity: 1;
          color: @subtext0;
        }
        .calendar {
          .calendar-color-w {
            color: @text;
          }
          .calendar-color-s {
            color: @yellow;
          }
          .calendar-color-c {
            color: @subtext1;
          }
          .calendar-color-g3 {
            color: darken(@green, 3%);
          }
          .calendar-color-g2 {
            color: @green;
          }
          .calendar-color-g4 {
            color: darken(@green, 3.5%);
          }
          .calendar-color-u {
            color: @sky;
          }
          .calendar-color-a {
            color: @subtext0;
          }
          .calendar-color-g1 {
            color: darken(@green, 2.5%);
          }
          .calendar-color-g0 {
            color: darken(@green, 2%);
          }
          .calendar-color-l {
            color: @red;
          }
          .calendar-mark-complete {
            color: @yellow;
          }
          .calendar-mark-verycomplete {
            color: @yellow;
          }
          .calendar-day {
            color: @subtext1;
          }
          #calendar-countdown {
            color: @subtext1;
          }

          span {
            color: @surface0;
          }

          a {
            color: @surface2;
          }
        }

        .day-success {
          color: @yellow;
          text-shadow: 0 0 5px @yellow;
        }

        .stats-both {
          color: @yellow;
        }

        .stats-firstonly {
          color: @overlay0;
        }

        a:hover {
          background-color: @mantle !important;
        }

        input[type="text"],
        textarea,
        code::before {
          border-color: @surface0;
          background: @crust;
        }
      }
    }
  }
}

/* ==UserStyle==
@name ChatGPT Catppuccin
@namespace github.com/catppuccin/userstyles/styles/chatgpt
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/chatgpt
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/chatgpt/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Achatgpt
@description Soothing pastel theme for ChatGPT
@author Catppuccin
@license MIT

@preprocessor  less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("chatgpt.com") {
  // TODO: Codemirror syntax highlighting.

  .light {
    #catppuccin(@lightFlavor);
  }

  .dark {
    #catppuccin(@darkFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    * {
      --text-primary: @text;
      --text-secondary: @subtext1;
      --text-tertiary: @subtext0;
      --text-quaternary: @overlay2;
      --bg-primary: @base;
      --bg-secondary: @surface0;
      --bg-tertiary: @surface1;

      --bg-secondary-surface: @mantle; // sidebar

      --bg-elevated-primary: @base; // settings main panel
      --bg-elevated-secondary: @mantle;

      --bg-tooltip: @crust;

      --main-surface-primary: @base;
      --main-surface-secondary: @surface0;
      --main-surface-tertiary: @surface1;
      --interactive-bg-secondary-hover: @surface1;
      --interactive-bg-secondary-press: @surface0;

      --interactive-label-accent-default: @accent; // some dropdowns in settings

      --border-light: @surface0;
      --border-default: @surface1;
      --border-medium: @surface2;
      --interactive-border-focus: @overlay0;

      --theme-user-msg-bg: @surface0;
      --theme-user-msg-text: @text;
      --theme-submit-btn-bg: @accent;
      --theme-submit-btn-text: @base;

      --theme-secondary-btn-bg: @surface1;
      --theme-secondary-btn-text: @text;

      --sidebar-surface: @mantle; // modal backgrounds
      --sidebar-surface-primary: @mantle; // syntax highlighted code block backgrounds

      --surface-hover: @surface0; // some button hovers

      --icon-tertiary: @overlay2;

      --text-status-error: @red;

      // chat input prompt border
      --shadow-color-1: fade(@mantle, 50%);
      --shadow-color-2: fade(@text, 80%);

      .__menu-item[data-sidebar-item] {
        --menu-item-highlighted: @surface0;
      }

      .__menu-item[data-color="danger"] {
        --menu-item-highlighted: fade(@red, 20%);
        --menu-item-active: fade(@red, 30%);
        --menu-item-open: fade(@red, 30%);
      }

      /* Markdown */

      /* Inline code */
      code:not(pre > code) {
        background-color: @surface0;
      }

      code[class*="language-"],
      pre[class*="language-"],
      code.hljs {
        color: @text !important;
      }

      /* Components */

      .btn-primary {
        background-color: @text;
        color: @base;
      }

      .btn-purple {
        color: @base;
        background-color: @accent;

        &:hover {
          background-color: lighten(@accent, 5%);
        }

        &:focus, &:active {
          background-color: darken(@accent, 5%);
        }
      }

      .btn-danger-outline {
        color: @red;
        border-color: @red;
      }

      .btn-ghost {
        &:not(:disabled) {
          &:hover {
            background-color: @surface0;
          }
        }
      }

      /* Dark Overrides */
      .bg-token-bg-primary {
        background-color: var(--bg-primary);
      }
      .bg-token-main-surface-primary {
        background-color: var(--main-surface-primary);
      }
      .bg-token-sidebar-surface {
        background-color: var(--sidebar-surface);
      }

      /* Tailwind Utilities */
      .__tailwind-utility(@color, @shade, @value) {
        .text-@{color}-@{shade},
        .dark\:text-@{color}-@{shade} {
          color: @value;
        }
        .bg-@{color}-@{shade},
        .dark\:bg-@{color}-@{shade} {
          background-color: @value;
        }
        .border-@{color}-@{shade} {
          border-color: @value;
        }
        .radix-state-checked\:bg-@{color}-@{shade}[data-state="checked"] {
          background-color: @value;
        }
      }

      .__tailwind-utility(green, 600, @green); // confirmation toasts
      .__tailwind-utility(red, 500, @red); // failure toasts
      .__tailwind-utility(blue, 400, @accent); // toggled checkmarks
      .__tailwind-utility(gray, 600, @overlay0); // untoggled checkmarks
      .__tailwind-utility(gray, 500, @overlay2); // faint text in/and dividers

      .text-white {
        color: @base;
      }

      .bg-black {
        background-color: @mantle;
      }
    }
  }
}

@-moz-document domain("auth.openai.com") {
  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    color: @text;

    background-color: @base;
    --main-page-background: @base;

    // Logo
    a[href="https://chatgpt.com"] > svg {
      filter: @text-filter;
    }

    --text-primary: @text;
    --text-secondary: @subtext1;
    --text-tertiary: @subtext0;
    --text-placeholder: @subtext0; // form field labels above the input (e.g. "Email" and "Password")

    --accent-blue: @accent;
    --link: @accent;

    --border-medium: @surface2;

    --button-primary-background: @text;
    --button-primary-hover: @subtext1;
    --button-text-on-primary: @base;

    --button-outline-hover: @surface0;

    --gray-100: @surface2; // divider lines

    input {
      color: @text;
    }

    [class*="_toggleVisibilityButton"]:where(:hover, :focus-visible)::before {
      background-color: @surface0;
    }

    [data-overlay-container] [class*="_tooltip"] {
      --tooltip-background-color: @mantle !important;
      --tooltip-color: @text !important;
    }
  }
}

/* ==UserStyle==
@name Claude Catppuccin
@namespace github.com/catppuccin/userstyles/styles/claude
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/claude
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/claude/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Aclaude
@description Soothing pastel theme for Claude
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("claude.ai") {
  :root[data-color-version="v2"] {
    &[data-mode="dark"] {
      #catppuccin(@darkFlavor);
    }
    &[data-mode="light"] {
      #catppuccin(@lightFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    --accent-brand: #hslify(@accent)[];
    --accent-000: #hslify(@accent)[];
    --accent-100: #hslify(@accent)[];
    --accent-200: #hslify(lighten(@accent, 5%))[];
    --accent-900: #hslify(darken(@accent, 10%))[];
    --accent-main-000: #hslify(@accent)[];
    --accent-main-100: #hslify(@accent)[];
    --accent-main-200: #hslify(@accent)[];
    --accent-main-900: #hslify(@accent)[];
    --accent-pro-000: #hslify(@accent)[];
    --accent-pro-100: #hslify(@accent)[];
    --accent-pro-200: #hslify(@accent)[];
    --accent-pro-900: #hslify(@accent)[];
    --accent-secondary-000: #hslify(@accent)[];
    --accent-secondary-100: #hslify(@accent)[];
    --accent-secondary-200: #hslify(@accent)[];
    --accent-secondary-900: #hslify(@accent)[];
    --bg-000: #hslify(@surface0)[];
    --bg-100: #hslify(@base)[];
    --bg-200: #hslify(@mantle)[];
    --bg-300: #hslify(@surface0)[];
    --bg-400: #hslify(@surface1)[];
    --bg-500: #hslify(@surface2)[];
    --brand-000: #hslify(@accent)[];
    --brand-100: #hslify(lighten(@accent, 5%))[];
    --brand-200: #hslify(lighten(@accent, 5%))[];
    --brand-900: #hslify(@crust)[];
    --border-000: #hslify(@base)[];
    --border-100: #hslify(@crust)[];
    --border-200: #hslify(@crust)[];
    --border-300: #hslify(@overlay0)[];
    --border-400: #hslify(@overlay1)[];
    --border-500: #hslify(@overlay2)[];
    --danger-000: #hslify(@maroon)[];
    --danger-100: #hslify(@red)[];
    --danger-200: #hslify(@red)[];
    --danger-900: #hslify(@pink)[];
    --oncolor-000: #hslify(darken(@mantle, 5%))[];
    --oncolor-100: #hslify(@mantle)[];
    --oncolor-200: #hslify(@mantle)[];
    --oncolor-300: #hslify(lighten(@mantle, 5%))[];
    --success-000: #hslify(@green)[];
    --success-100: #hslify(lighten(@green, 5%))[];
    --success-200: #hslify(lighten(@green, 5%))[];
    --success-900: #hslify(lighten(@green, 15%))[];
    --text-000: #hslify(darken(@text, 5%))[];
    --text-100: #hslify(@text)[];
    --text-200: #hslify(@text)[];
    --text-300: #hslify(@subtext0)[];
    --text-400: #hslify(@subtext1)[];
    --text-500: #hslify(@subtext0)[];
    --warning-000: #hslify(@yellow)[];
    --warning-100: #hslify(lighten(@yellow, 5%))[];
    --warning-200: #hslify(lighten(@yellow, 5%))[];
    --warning-900: #hslify(lighten(@yellow, 15%))[];

    /* Side bar */
    nav.\!bg-bg-200 {
      background: @mantle !important;
    }

    /* Code blocks */
    .code-block__code {
      background: @crust !important;

      code {
        /* Default color */
        span {
          color: @text !important;
        }

        /* Green */
        span.token[style="color: rgb(152, 195, 121);"] {
          color: @green !important;
        }

        /* Yellow */
        span.token[style="color: rgb(209, 154, 102);"] {
          color: @yellow !important;
        }

        /* Blue */
        span.token[style="color: rgb(97, 175, 239);"] {
          color: @blue !important;
        }

        /* Red */
        span.token[style="color: rgb(224, 108, 117);"] {
          color: @red !important;
        }

        /* Magenta */
        span.token[style="color: rgb(198, 120, 221);"] {
          color: @mauve !important;
        }

        /* Gray */
        span.token[style="color: rgb(171, 178, 191);"] {
          color: @overlay2 !important;
        }
      }
    }

    /* Inline code */
    code.text-danger-000 {
      color: @accent !important;
    }

    /* Tooltip */
    div.bg-black\/80 {
      background: @crust !important;
    }
    div.text-white {
      color: @text !important;
    }

    /* Logo */
    div.text-\[\#D97757\] {
      color: @accent !important;
    }

    /* "New chat" plus icon */
    div.text-always-white svg {
      color: @base !important;
    }

    /* "Subscribe to Pro" and "Create Team Account" buttons */
    button.bg-accent-pro-100 > span.inline-block {
      color: @base !important;
    }

    /* Pay monthly/annually buttons */
    button.bg-accent-secondary-900 {
      span.text-text-000 {
        color: @base !important;
      }
      span.text-text-300 {
        color: @surface2 !important;
      }
      div.bg-accent-secondary-000 {
        background: darken(@accent, 15%) !important;
      }
    }

    /* Delete conversation button */
    div.\!text-danger-000.\[\&\[data-highlighted\]\]\:bg-danger-900[data-highlighted] {
      background: fade(@red, 20%) !important;
    }

    /* Checkbox */
    input[type="checkbox"] + div.bg-bg-000 {
      background: @text !important;
    }

    /* "Add writing example" button */
    button.\!text-accent-secondary-100.bg-accent-secondary-900 {
      color: @base !important;
      &:hover {
        color: @text !important;
      }
    }

    /* "Describe your style" list */
    button.\!bg-accent-secondary-900.text-accent-secondary-000 {
      color: @base !important;
    }

    /* "Be as descriptive as possible..." helper text */
    div.bg-accent-secondary-900.text-text-200 {
      color: @base !important;
    }

    /* "Preview with an example..." pills */
    button.hover\:bg-accent-secondary-900.hover\:text-accent-secondary-000 {
      color: @accent !important;
      &:hover {
        color: @base !important;
      }
    }

    /* "Previewing with ..." dropdown button */
    button.\!text-accent-secondary-100.hover\:\!bg-accent-secondary-900 {
      color: @accent !important;
      &:hover {
        color: @base !important;
      }
    }

    /* White background (e.g., toggle switch thumb) */
    .bg-white {
      background-color: @text;
    }
  }
}

#hslify(@color) {
  @raw: e(%("%s %s% %s%", hue(@color), saturation(@color), lightness(@color)));
}

