        + a[href^="/settings/"][href$="/password"]
    ),
    /* Delete account */
    p:has(+ a[href^="/settings/"][href$="/delete-account"]) {
      color: @text;
    }

    /* Access tokens settings */
    form#tokens {
      table {
        td {
          span {
