      background-color: fade(@accent, 20%);
    }
    button[aria-label^="Delete token ending in"] {
      ._305a9f55 ._038c0473 & {
        border-color: @surface2;
      }
      &.b55db0e2:hover {
        border-color: @red;
        background-color: @red;
        color: @base;
      }
    }

    /* 2FA authentication page */
    ._75ce47e7 {
      background-color: @base;

      ._71252860,
      .d7eb966d {
