      &::before {
        background-image: @npmGradient;
      }

      section {
        box-shadow: 0 10px 20px rgba(0, 0, 0, 0.6);
      }

      div[role="radiogroup"] {
        color: @text;
        background-color: @surface0;
      }

      #gat-banner span {
        color: @yellow;
      }
    }

    /* Create organization page */
    .acb78000::before {
      background-image: @npmGradient;
    }
    /* Step 1: create an org */
    .e99f3f5d {
