/* ==UserStyle==
@name Pinterest Catppuccin
@namespace github.com/catppuccin/userstyles/styles/pinterest
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/pinterest
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/pinterest/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Apinterest
@description Soothing pastel theme for Pinterest
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document regexp(
    "^https?:\\/\\/(www|[a-z]{2}).pinterest.(com(.(au|mx))?|co(.(uk|kr))?|at|ca|ch|cl|de|dk|es|fr|ie|it|jp|nz|ph|pt|ru|se)\\/.*"
  ) {
  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }

    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    &,
    body {
      color: @text;
      background: @base;
    }

    --sema-color-background-default: @base;
    --sema-color-background-secondary: @surface0;
    --sema-color-hover-background-secondary: @surface1;
    --sema-color-background-tertiary: @overlay0; // send message to conversation button
    --sema-color-hover-background-tertiary: @overlay2;
    --sema-color-text-default: @text;
    --sema-color-text-subtle: @subtext1;
    --sema-color-text-link: @accent; // links / messages username
    --sema-color-text-dark: @text; // commenter username / bar pills text
    --sema-color-text-light: if(
      @flavor = latte,
      @base,
      @text
    ); // Explore suggested articles link
    --sema-color-icon-primary: @accent; // logo
    --sema-color-icon-inverse: @mantle;
    --sema-color-border-decorative: @surface2;
    --sema-color-border-interactive: @overlay0; // form inputs
    --sema-color-hover-border-interactive: @overlay1;
    --sema-color-border-focus-outer-default: @accent;
    --sema-color-border-focus-inner-default: @base;
    --sema-color-border-disabled: @surface1;
    --sema-color-icon-disabled: @subtext0; // board actions in organize mode

    /* Pins */
    --sema-color-background-primary: @accent;
    --sema-color-hover-background-primary: darken(@accent, 5%);
    --sema-color-background-wash-light: @base;
    --sema-color-pressed-background-primary: darken(@accent, 5%);
    --comp-button-color-background-primary-selected: @surface1; // select dropdown
    --comp-button-color-background-tertiary-semi-transparent-default: fade(
      @base,
      50%
    ); // pin action
    --comp-button-color-hover-background-tertiary-semi-transparent-default: fade(
      @base,
      50%
    );

    [data-test-id="more-description-container"] {
      background-color: @base !important;
      [style*="background: linear-gradient"] {
        background: linear-gradient(90deg, transparent 0%, @base 100%)
          !important;
      }
    }
    [data-test-id="closeup-metadata-details-divider"] {
      border-top-color: var(--sema-color-border-decorative) !important;
    }
    [data-test-id="PinBetterSaveDropdown"] {
      --sema-color-text-inverse: @text;
      --sema-color-icon-inverse: @text;
    }

    --sema-color-text-error: @red;
    --sema-color-background-error-default: @maroon;
    --sema-color-icon-error: @red;
    --sema-color-border-error: @red;

    /* Boards */
    --sema-color-background-checked: @accent; // "Secret" toggle
    --sema-color-hover-background-checked: darken(@accent, 5%);
    --sema-color-pressed-background-checked: darken(@accent, 10%);
    --comp-switch-color-background-container-enabled-off: @surface2;
    --comp-switch-color-hover-background-container-enabled-off: @overlay0;
    --comp-button-color-hover-background-secondary-default: @surface1; // "Cancel" button hover

    [data-test-id="profile-board-card"] [style*="border-color: white;"] {
      // pin preview collage images
      border-color: @base !important;
    }

    --sema-color-border-inverse: @base; // around profile pictures under previews
    --sema-color-pressed-background-default: @surface2; // "Edit" icon / edit modal "X" icon buttons
    --comp-button-color-pressed-background-secondary-default: @surface2; // active "View profile" button
    --sema-color-pressed-background-elevation: @surface2; // plus action

    // "select and reorder" / organize
    [data-test-id="pinRepSelectionBorder"] {
      &[style*="border-color: rgb(255, 255, 255);"] {
        border-color: @base !important;
      }
      &[style*="box-shadow: rgb(255, 255, 255) 0px 0px 0px 3px inset;"] {
        box-shadow: @accent 0 0 0 3px inset !important;
      }
    }

    /* Sidebar */
    --sema-color-icon-default: @text;
    --sema-color-hover-background-default: @surface0;
    --base-color-grayscale-100: @surface0; // border
    [aria-label="You have new Updates"] {
      --sema-color-text-light: @base; // notification badge
    }
    // Explore
    [data-test-id="topic-rep-title"] {
      --sema-color-text-inverse: @text; // Explore categories
    }
    --sema-color-background-elevation: @mantle;
    --sema-color-hover-background-elevation: @base;
    // Create
    --sema-color-icon-dark: @text;
    [data-test-id="drag-behavior-container"] {
      --sema-color-text-default: if(
        @flavor = latte,
        @text,
        @surface2
      ); // drag container error
    }
    // Tooltips
    --sema-color-background-inverse: @text;
    --sema-color-text-inverse: @base;

    /* Search */
    --sema-color-icon-subtle: @overlay2;

    #searchBoxContainer > div {
      background-color: @mantle !important;

      > div[style*="box-shadow:"] {
        // on focus
        box-shadow: fade(@accent, 50%) 0 0 0 4px !important;
      }

      // divider
      [style*="background:#d8d8d8;"],
      [style*="background: rgb(216, 216, 216);"] {
        background: @surface1 !important;
      }

      input {
        color: @subtext1 !important;
      }
    }

    [id^="SuggestionGroup-Option"][aria-selected="true"] > a > div {
      background-color: @surface1;
    }

    /* Home */
    [data-test-id="homefeed-feed"]
      div:has(
        > [data-root-margin="more-ideas-tabs"]
      )[style*="background-color: rgb(255, 255, 255);"] {
      background-color: @base !important;
    }

    --sema-color-background-selected: @accent; // active tab underline
    --sema-color-hover-background-selected: darken(@accent, 5%);
    --sema-color-pressed-background-selected: darken(@accent, 10%);

    // share modal
    [data-test-id="lego-share-social-bar-auth"] button {
      background-color: @base !important;
    }

    /* Settings */
    --sema-color-text-disabled: @overlay2; // disabled "Reset"/"Save" buttons

    /* Messages */
    textarea#messageDraft {
      background-color: transparent !important;
      color: @subtext1;
      caret-color: @text !important;
    }

    div[data-test-id="add-pin-to-conversation"] {
      div[style="border: 1px solid rgb(218, 218, 218); box-shadow: rgba(0, 132, 255, 0) 0px 0px 0px 4px; min-height: 48px; width: 100%;"] {
        border-color: @mantle !important;
      }

      div[style="border: 1px solid transparent; box-shadow: rgba(0, 132, 255, 0.5) 0px 0px 0px 4px; min-height: 48px; width: 100%;"] {
        box-shadow: fade(@accent, 50%) 0 0 0 4px !important;
      }
    }

    /* Loading */
    .mainContainer
      > div[style*="background-color: rgba(255, 255, 255, 0.5); height: 100%; width: 100%; z-index: 1;"] {
      background-color: @base !important;
    }

    /* Emoji Picker */
    .EmojiPickerReact {
      --epr-bg-color: @base;
      --epr-text-color: @text;
      --epr-picker-border-color: @base;
      --epr-category-label-bg-color: @base;
      --epr-search-input-bg-color: @mantle;
      --epr-skin-tone-picker-menu-color: @mantle;
      --epr-category-icon-active-color: @accent;
      --epr-highlight-color: @accent;
      --epr-hover-bg-color: @surface0;
      --epr-focus-bg-color: @surface0;
    }

    /* suggestion bar */
    --sema-color-pressed-background-secondary: @surface2;
    [data-test-id="one-bar-pill"] {
      --sema-color-text-dark: if(@flavor = latte, @text, @base);
    }
    [data-test-id="one-bar-navigation-arrows"] {
      &[style*="to left"]:not([style*="to right"]) {
        background: linear-gradient(to left, @base, transparent 40px)
          !important;
      }
      &[style*="to right"]:not([style*="to left"]) {
        background: linear-gradient(to right, @base, transparent 40px)
          !important;
      }
      &[style*="to left"][style*="to right"] {
        background:
          linear-gradient(to left, @base, transparent 40px),
          linear-gradient(to right, @base, transparent 40px) !important;
      }
    }
    [data-test-id="multi-select-filter-fade-bottom-edge"] {
      background: linear-gradient(0deg, @base 0%, transparent 100%) !important;
    }

    /* Toasts */
    --comp-toast-color-background-default: @overlay2;

    /* SaveButton */
    [data-test-id="SaveButton"] > [class^="SaveButton"] {
      // Your saved ideas pins "Save" button
      background-color: var(--sema-color-background-primary);
      &:hover {
        background-color: var(--sema-color-hover-background-primary);
      }
    }
  }
}

/* ==UserStyle==
@name Proton Catppuccin
@namespace github.com/catppuccin/userstyles/styles/proton
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/proton
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/proton/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Aproton
@description Soothing pastel theme for Proton
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document regexp(
    "https://(account|mail|drive|calendar|lumo).proton.me/.*$"
  ) {
  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    svg.logo {
      @accentH: hue(@accent);
      @protonH: hue(#6d4aff);

      .replaceColor(@org, @property) {
        &[@{property}="@{org}"] {
          @hDiff: @protonH - hue(@org);
          @{property}: hsl(
            @accentH - @hDiff,
            saturation(@org) - 30%,
            lightness(@org)
          );
        }
      }

      /* deno-fmt-ignore */
      path {
        .replaceColor(#B8D7FF, fill);
        .replaceColor(#8F69FF, fill);
        .replaceColor(#6D4AFF, fill);
        .replaceColor(#FFBB93, fill);
        .replaceColor(#85D4F5, fill);
        .replaceColor(#D6F1FC, fill);
      }

      /* deno-fmt-ignore */
      defs stop {
        .replaceColor(#E3D9FF, stop-color);
        .replaceColor(#7341FF, stop-color);
        .replaceColor(#6D4AFF, stop-color);
        .replaceColor(#AA8EFF, stop-color);
        .replaceColor(#06B8FF, stop-color);
        .replaceColor(#BFE8FF, stop-color);
        .replaceColor(#BFABFF, stop-color);
        .replaceColor(#FF50C3, stop-color);
        .replaceColor(#B487FF, stop-color);
        .replaceColor(#FFC8FF, stop-color);
        .replaceColor(#8EFFEE, stop-color);
        .replaceColor(#C9C7FF, stop-color);
        .replaceColor(#00F0C3, stop-color);
        .replaceColor(#FFD580, stop-color);
        .replaceColor(#F6C592, stop-color);
        .replaceColor(#EBB6A2, stop-color);
        .replaceColor(#DFA5AF, stop-color);
        .replaceColor(#D397BE, stop-color);
        .replaceColor(#C486CB, stop-color);
        .replaceColor(#B578D9, stop-color);
        .replaceColor(#A166E5, stop-color);
        .replaceColor(#8B57F2, stop-color);
        .replaceColor(#704CFF, stop-color);
        .replaceColor(#B39FFB, stop-color);
        .replaceColor(#FFE8DB, stop-color);
        .replaceColor(#957AFD, stop-color);
        .replaceColor(#FFC6C6, stop-color);
        .replaceColor(#FA528E, stop-color);
        .replaceColor(#FF8065, stop-color);
        .replaceColor(#FFA51F, stop-color);
        .replaceColor(#34B8EE, stop-color);
      }
    }

    &,
    .ui-prominent,
    .ui-standard {
      #lightenOrDarken(@color, @value) {
        @result: if(
          @flavor = latte,
          lighten(@color, @value),
          darken(@color, @value)
        );
      }

      #darkenOrLighten(@color, @value) {
        @result: if(
          @flavor = latte,
          darken(@color, @value),
          lighten(@color, @value)
        );
      }

      --primary-minor-2: #lightenOrDarken(@accent, 60%)[];
      --primary-minor-1: #lightenOrDarken(@accent, 50%)[];
      --primary: @accent;
      --primary-major-1: #darkenOrLighten(@accent, 4%)[];
      --primary-major-2: #darkenOrLighten(@accent, 8%)[];
      --primary-major-3: #darkenOrLighten(@accent, 12%)[];
      --primary-contrast: @mantle;
      --signal-danger-minor-2: #lightenOrDarken(@maroon, 40%)[];
      --signal-danger-minor-1: #lightenOrDarken(@maroon, 30%)[];
      --signal-danger: @maroon;
      --signal-danger-major-1: #darkenOrLighten(@maroon, 4%)[];
      --signal-danger-major-2: #darkenOrLighten(@maroon, 8%)[];
      --signal-danger-major-3: #darkenOrLighten(@maroon, 12%)[];
      --signal-danger-contrast: @mantle;
      --signal-warning-minor-2: #lightenOrDarken(@peach, 40%)[];
      --signal-warning-minor-1: #lightenOrDarken(@peach, 30%)[];
      --signal-warning: @peach;
      --signal-warning-major-1: #darkenOrLighten(@peach, 4%)[];
      --signal-warning-major-2: #darkenOrLighten(@peach, 8%)[];
      --signal-warning-major-3: #darkenOrLighten(@peach, 12%)[];
      --signal-warning-contrast: @mantle;
      --signal-success-minor-2: #lightenOrDarken(@green, 40%)[];
      --signal-success-minor-1: #lightenOrDarken(@green, 30%)[];
      --signal-success: @green;
      --signal-success-major-1: #darkenOrLighten(@green, 4%)[];
      --signal-success-major-2: #darkenOrLighten(@green, 8%)[];
      --signal-success-major-3: #darkenOrLighten(@green, 12%)[];
      --signal-success-contrast: @mantle;
      --signal-info-minor-2: #lightenOrDarken(@blue, 40%)[];
      --signal-info-minor-1: #lightenOrDarken(@blue, 30%)[];
      --signal-info: @blue;
      --signal-info-major-1: #darkenOrLighten(@blue, 4%)[];
      --signal-info-major-2: #darkenOrLighten(@blue, 8%)[];
      --signal-info-major-3: #darkenOrLighten(@blue, 12%)[];
      --signal-info-contrast: @mantle;
      --interaction-norm-minor-2: #lightenOrDarken(@accent, 40%)[];
      --interaction-norm-minor-1: #lightenOrDarken(@accent, 30%)[];
      --interaction-norm: @accent;
      --interaction-norm-major-1: #darkenOrLighten(@accent, 4%)[];
      --interaction-norm-major-2: #darkenOrLighten(@accent, 8%)[];
      --interaction-norm-major-3: #darkenOrLighten(@accent, 12%)[];
      --interaction-norm-contrast: @mantle;
      --interaction-weak-minor-2: #lightenOrDarken(@surface0, 20%)[];
      --interaction-weak-minor-1: #lightenOrDarken(@surface0, 10%)[];
      --interaction-weak: @surface0;
      --interaction-weak-major-1: #darkenOrLighten(@surface0, 4%)[];
      --interaction-weak-major-2: #darkenOrLighten(@surface0, 8%)[];
      --interaction-weak-major-3: #darkenOrLighten(@surface0, 12%)[];
      --interaction-weak-contrast: @text;
      --text-norm: @text;
      --text-weak: @subtext0;
      --text-hint: @subtext1;
      --text-disabled: @overlay1;
      --text-invert: @crust;
      --text-markdown: @text;
      --field-norm: @overlay2;
      --field-hover: @overlay1;
      --field-disabled: @overlay0;
      --field-focus: @accent;
      --field-highlight: fade(@accent, 70%);
      --focus-outline: @accent;
      --focus-ring: fade(@accent, 40%);
      --link-norm: @blue;
      --link-hover: @lavender;
      --link-active: @sky;
      --markdown-pre-background: @mantle;
      --border-norm: @overlay0;
      --border-weak: @surface1;
      --background-norm: @base;
      --background-weak: @mantle;
      --background-strong: @crust;
      --background-invert: @text;
      --interaction-default: transparent;
      --interaction-default-hover: fade(@overlay1, 20%);
      --interaction-default-active: fade(@overlay1, 40%);
      --shadow-primary-color: red(@accent) green(@accent) blue(@accent);
      --shadow-norm-opacity: 0.5;
      --shadow-raised-opacity: 1;
      --shadow-lifted-opacity: 0.75;
      --backdrop-norm: fade(@crust, 50%);
      --optional-scrollbar-thumb-color: @surface0;
      --optional-scrollbar-thumb-hover-color: @surface2;
      --optional-link-norm: var(--interaction-norm-major-1);
      --optional-link-hover: var(--interaction-norm-major-2);
      --optional-link-active: var(--interaction-norm-major-3);
      --optional-background-elevated: @surface0;
      --optional-background-lowered: var(--background-norm);
      --optional-email-item-unread-background-color: var(--background-weak);
      --optional-email-item-read-background-color: var(--background-norm);
      --optional-email-item-read-text-color: var(--text-weak);
      --optional-mini-calendar-today-color: @text;
      --optional-logo-text-proton-color: @text;
      --optional-logo-text-product-color: @text;
      --favorite-icon-color: @peach;
    }

    .ui-prominent {
      --background-norm: @mantle;
      --background-weak: @base;
      --background-strong: @crust;
    }

    .button-promotion {
      --upgrade-color-stop-1: @red;
      --upgrade-color-stop-2: @blue;
    }

    .item-container-row:not(.item-is-selected):hover,
    .item-container:not(.item-is-selected):hover {
      box-shadow: none;
      background-color: var(--navigation-current-item-background-color);
      color: var(--email-item-unread-text-color);
    }

    .message-content:not(.plain) .message-iframe iframe {
      color-scheme: light;
    }

    @media (min-width: 28.135em) {
      .sign-layout-bg {
        background: linear-gradient(
          68.66deg,
          desaturate(@mantle, 5%) 1.3%,
          desaturate(@base, 5%) 50%
        );
      }
    }

    /* Proton Lumo */

    header {
      a[aria-label="Go to Lumo homepage"] img {
        filter: @accent-filter;
      }
    }

    .whats-new-section {
      background: @accent;
    }

    .new-label {
      background-color: @accent;
      color: @crust;
    }

    .lumo-sidebar {
      background: @mantle;
      a.lumo-plus-button svg path {
        fill: @accent;
      }
    }

    .lumo-input-container.ghost-mode {
      background-color: @crust;
      --ghost-text: @text;
      --ghost-text-weak: @subtext0;
      .lumo-input {
        background-color: @mantle;
      }
    }

    div[style*="background: rgb(40, 44, 52);"],
    div[style*="background: rgb(250, 250, 250);"] {
      background: @mantle !important;

      span {
        color: @text !important;
      }

      span.token[style*="color: rgb(92, 99, 112);"],
      span.token[style*="color: rgb(160, 161, 167);"] {
        color: @overlay2 !important;
      }

      span.token[style*="color: rgb(97, 175, 239);"],
      span.token[style*="color: rgb(64, 120, 242);"] {
        color: @blue !important;
      }

      span.token[style*="color: rgb(152, 195, 121);"],
      span.token[style*="color: rgb(80, 161, 79);"] {
        color: @green !important;
      }

      span.token[style*="color: rgb(209, 154, 102);"],
      span.token[style*="color: rgb(183, 107, 1);"] {
        color: @peach !important;
      }

      span.token[style*="color: rgb(198, 120, 221);"],
      span.token[style*="color: rgb(166, 38, 164);"] {
        color: @mauve !important;
      }

      span.token[style*="color: rgb(224, 108, 117);"],
      span.token[style*="color: rgb(228, 86, 73);"] {
        color: @red !important;
      }
    }
  }
}

/* ==UserStyle==
@name React.dev Catppuccin
@namespace github.com/catppuccin/userstyles/styles/react.dev
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/react.dev
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/react.dev/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Areact.dev
@description Soothing pastel theme for React.dev
@author Catppuccin
@license MIT
@preprocessor less

@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("react.dev") {
  html.dark {
    #catppuccin(@darkFlavor);
  }
  html {
    #catppuccin(@lightFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    //svg styling

    svg {
      color: @accent !important;
    }

    //text styling

    .text-primary {
      color: @text;
    }

    .dark\:text-primary-dark {
      color: @text;
    }

    .dark\:text-white {
      color: @text;
    }

    .text-secondary {
      color: @text;
    }

    .text-gray-30 {
      color: @subtext1;
    }

    .text-red-50,
    .text-red-30 {
      color: @red !important;
    }

    .text-gray-50 {
      color: @subtext0;
    }

    // color divs text

    #color-and-svg(@color) {
      color: @color !important;
      svg {
        color: @color !important;
      }
    }
    .text-red-50, .text-red-40 {
      #color-and-svg(@red);
    }
    .text-purple-50, .text-purple-30, .text-purple-60 {
      #color-and-svg(@mauve);
    }
    .text-blue-50, .text-blue-40, .text-blue-60 {
      #color-and-svg(@blue);
    }
    .text-yellow-40, .text-yellow-50, .text-yellow-60 {
      #color-and-svg(@yellow);
    }

    .text-green-60, .text-green-40 {
      color: @green !important;
    }

    .text-tertiary,
    .text-tertiary-dark {
      color: @subtext0;
    }

    .text-link,
    .text-link-dark {
      color: @accent;
    }

    //hover styling

    .hover\:text-link:hover, .text-link:hover, .text-link-dark:hover {
      color: @accent;
    }

    .hover\:bg-gray-80:hover,
    .hover\:bg-gray-5:hover {
      background-color: @mantle;
    }

    .hover\:bg-card:hover {
      background-color: @crust;
    }

    //code stylizing

    a > code {
      color: @accent !important;
    }

    .console-block code {
      background-color: @surface1 !important;
      color: @red !important;
    }

    .sp-wrapper {
      --sp-colors-accent: @accent;
      --sp-colors-clickable: @flamingo;
      --sp-colors-disabled: @text;
      --sp-colors-error: @red;
      --sp-colors-error-surface: @maroon;
      --sp-colors-surface1: @surface0;
      --sp-colors-surface2: @surface1;
      --sp-syntax-color-plain: @text;
      --sp-syntax-color-comment: @overlay2;
      --sp-syntax-color-keyword: @mauve;
      --sp-syntax-color-tag: @blue;
      --sp-syntax-color-punctuation: @overlay2;
      --sp-syntax-color-definition: @yellow;
      --sp-syntax-color-property: @blue;
      --sp-syntax-color-static: @peach;
      --sp-syntax-color-string: @green;
    }

    //border styling

    .border-blue-40 {
      border-color: @blue;
    }

    .border-b-4 {
      border-color: @text;
    }

    .border-yellow-40 {
      border-color: @yellow;
    }

    .border-purple-40 {
      border-color: @lavender;
    }

    .border-purple-10 {
      border-color: @mauve;
    }

    .dark\:border-purple-30, .border-purple-30 {
      border-color: @mauve;
    }

    .border-green-40 {
      border-color: @green;
    }

    .hover\:border-gray-10:hover {
      border-color: @accent;
    }

    .border-gray-300, .bg-gray-90 {
      border-color: @overlay2;
    }

    .border-gray-20 {
      border-color: @overlay1;
    }

    .border-link:hover {
      border-color: @accent;
    }

    .dark\:border-link-dark {
      border-color: @accent;
    }

    //backgrounds styling

    .bg-card-dark,
    .bg-card {
      background-color: @surface0;
    }

    .bg-highlight {
      background-color: @surface0;
    }

    .bg-highlight-dark {
      background-color: @surface0;
    }

    .bg-github-highlight {
      background-color: @surface0;
    }

    .bg-link {
      color: @surface0;
      background-color: @accent;
    }

    .bg-gradient-left,
    .bg-gradient-left-dark {
      background-image: conic-gradient(
        from 90deg at -10% 100%,
        @mantle 0deg,
        @base 90deg,
        @crust 1turn
      );
    }

    .bg-gray-3,
    .bg-gray-5 {
      background-color: @crust;
    }

    .bg-gray-40\/5,
    .bg-gray-60\/5 {
      background-color: @overlay1;
    }

    .bg-gray-40\/10,
    .bg-gray-60\/10 {
      background-color: @overlay0;
    }
    .bg-gray-30,
    .bg-gray-300,
    .bg-gray-70,
    .bg-gray-700 {
      background-color: @surface0;
    }

    .bg-gray-80,
    .bg-gray-200,
    .bg-gray-95 {
      background-color: @mantle;
    }

    .bg-black {
      background-color: @base;
    }

    #color-fragment-style(@divColor) {
      background-color: fade(@divColor, 40%);
      color: @text;

      p {
        color: @text;
      }

      button {
        color: @base !important;
        background-color: @divColor !important;

        svg {
          color: @base !important;
        }
      }

      .text-primary {
        color: @text;
      }

      .text-link {
        color: @accent;
      }

      .bg-highlight {
        color: @accent;
      }

      .bg-link {
        background-color: @accent;
        color: @text;
      }
    }

    .bg-green-5, .bg-green-60, .bg-green-40 {
      #color-fragment-style(@green);
    }

    .bg-red-5, .bg-red-60 {
      #color-fragment-style(@red);
    }

    .bg-yellow-5, .bg-yellow-60, .bg-yellow-40 {
      #color-fragment-style(@peach);
    }

    .bg-purple-5, .bg-purple-60, .bg-purple-40 {
      #color-fragment-style(@mauve);
    }

    .bg-blue-10, .bg-blue-60, .bg-blue-40 {
      #color-fragment-style(@blue);
    }

    .bg-red-30 {
      background-color: fade(@red, 10%);
    }

    .bg-gradient-right,
    .bg-gradient-right-dark {
      background-image: conic-gradient(
        from -90deg at 110% 100%,
        @crust 0deg,
        @base 90deg,
        @mantle 1turn
      );
    }

    .bg-white,
    .bg-wash {
      background-color: @base !important;
    }

    .bg-secondary-button {
      background-color: @surface1;
    }

    // outline styling

    .outline-link {
      outline-color: @accent;
    }

    .focus\:outline-link:focus {
      outline-color: @accent;
    }

    // docsearch styling

    --docsearch-modal-background: @base !important;
    --docsearch-hit-background: @mantle !important;
    --docsearch-highlight-color: @accent !important;
    --docsearch-primary-color: @accent !important;
    --docsearch-container-background: rgba(127, 132, 156, 0.8) !important;
    --docsearch-text-color: @text !important;
    --docsearch-logo-color: @blue !important;
    --docsearch-muted-color: @subtext0 !important;
    --docsearch-searchbox-background: @accent !important;
    --docsearch-searchbox-focus-background: @accent !important;
    --docsearch-hit-color: @crust !important;
    --docsearch-hit-active-color: @base !important;
    --docsearch-footer-background: @overlay0 !important;
    --docsearch-key-gradient: linear-gradient(
      -225deg,
      @base,
      @crust
    ) !important;

    .DocSearch-Form {
      background-color: @mantle;
      input {
        color: @text;
      }
      :focus-visible {
        outline-color: 2px solid @accent !important;
      }
    }

    .DocSearch-Hit {
      .DocSearch-Hit-title {
        color: @text;
      }

      svg {
        color: currentcolor !important;
      }

      .DocSearch-Hit-Tree {
        color: @base !important;
      }

      &[aria-selected="false"] {
        mark {
          color: @accent !important;
        }
        .DocSearch-Hit-Tree {
          color: @subtext0 !important;
        }
      }
    }

    .DocSearch-Hit-source {
      color: @text;
    }

    .DocSearch-Cancel {
      color: @accent;
    }

    .DocSearch-Footer {
      background-color: @base;

      [aria-label="Algolia"] {
        .cls-1,
        .cls-2 {
          fill: @accent !important;
        }
      }
    }
  }
}

/* ==UserStyle==
@name 7TV Catppuccin
@namespace github.com/catppuccin/userstyles/styles/seventv
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/seventv
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/seventv/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Aseventv
@description Soothing pastel theme for 7TV
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("7tv.app") {
  .light-theme {
    #catppuccin(@lightFlavor);
  }
  .dark-theme {
    #catppuccin(@darkFlavor);
  }

  .system-theme {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    background-color: @base;

    --secondary: @surface0;
    --secondary-text: @text;
    --secondary-hover: @surface0;
    --secondary-active: @surface0;
    --secondary-disabled: @crust;
    --secondary-border: transparent;
    --primary: @accent;
    --primary-text: @crust;
    --primary-hover: darken(@accent, 5%);
    --primary-active: darken(@accent, 5%);
    --primary-disabled: @subtext0;
    --primary-border: transparent;
    --bg-dark: @crust;
    --bg-medium: @mantle;
    --bg-light: @base;
    --text: @text;
    --text-light: @subtext0;
    --layout-border: transparent;
    --border-active: @base;
    --store: @mauve;
    --preview: @mantle;
    --danger: @peach;
    --approve: @green;
    --rename: @sapphire;
    --staff: @red;
    --staff-bg: fade(@red, 20%);
    --admin-merge: @mauve;
    --admin-unlist: @peach;

    .flag {
      &[style*="#57ab5a"] {
        color: @green !important;
        background-color: fade(@green, 20%) !important;
      }
      /* Emote is in selected emote set */
      &[style*="#529bf5"] {
        color: @accent !important;
        background-color: fade(@accent, 20%) !important;
      }
      /* Emote is unlisted */
      &[style*="#eb3d26"] {
        color: @red !important;
        &[style*="background-color"] {
          background-color: fade(@red, 20%) !important;
        }
      }
      /* Emote is trending */
      &[style*="#e0823d"] {
        color: @peach !important;
        &[style*="background-color"] {
          background-color: fade(@peach, 20%) !important;
        }
      }
      /* Emote is overlaying */
      &[style*="#fc8dc7"] {
        color: @pink !important;
        &[style*="background-color"] {
          background-color: fade(@pink, 20%) !important;
        }
      }
      /* Personal emote set */
      &[style*="#b083f0"] {
        color: @mauve !important;
      }
    }

    .badge {
      color: @base;
    }

    .emote,
    .emote-set {
      /* Emote is in selected emote set */
      &[style*="--highlight-active: #529bf5"] {
        --highlight: fade(@accent, 80%) !important;
        --highlight-active: @accent !important;
        &.emote-set .name {
          color: @accent !important;
        }
      }

      /* Emote is unlisted */
      &[style*="--highlight-active: #eb3d26"] {
        --highlight: fade(@red, 80%) !important;
        --highlight-active: @red !important;
      }

      /* Emote is trending */
      &[style*="--highlight-active: #e0823d"] {
        --highlight: fade(@peach, 80%) !important;
        --highlight-active: @peach !important;
      }

      /* Emote is overlaying */
      &[style*="--highlight-active: #fc8dc7"] {
        --highlight: fade(@pink, 80%) !important;
        --highlight-active: @pink !important;
      }

      /* Emote set is a personal emote set */
      &.emote-set[style*="--highlight-active: #b083f0"] {
        --highlight: fade(@mauve, 80%) !important;
        --highlight-active: @mauve !important;
        &.emote-set .name {
          color: @mauve !important;
        }
      }

      /* Emote set is a special emote set */
      &.emote-set[style*="--highlight-active: #fcc200"] {
        --highlight: fade(@yellow, 80%) !important;
        --highlight-active: @yellow !important;
        &.emote-set .name,
        &.emote-set .flag {
          color: @yellow !important;
        }
      }
    }

    img.image,
    .profile-picture,
    .profile-name .name,
    .user,
    .user-link,
    .username .name,
    .role > span,
    .side-bar .name,
    .roles > span {
      /* Admin */
      &[style*="255, 70, 70"] {
        &,
        span,
        img {
          color: @red !important;
          border-color: @red !important;
        }
      }

      /* Moderator */
      &[style*="50, 168, 82"] {
        &,
        span,
        img {
          color: @green !important;
          border-color: @green !important;
        }
      }

      &[style*="23, 235, 182"],
      &[style*="177, 235, 52"],
      &[style*="68, 194, 135"] {
        &,
        span {
          color: @teal !important;
          border-color: @teal !important;
        }
      }
      /* Event coordinator */
      &[style*="182, 56, 181"] {
        &,
        span,
        img {
          color: @pink !important;
          border-color: @pink !important;
        }
      }

      /* Verified */
      &[style*="145, 70, 255"] {
        &,
        span,
        img {
          color: @mauve !important;
          border-color: @mauve !important;
        }
      }
      /* Subscriber */
      &[style*="255, 170, 0"] {
        &,
        span,
        img {
          color: @yellow !important;
          border-color: @yellow !important;
        }
      }
    }

    .hero {
      svg {
        color: @text !important;
      }

      color: @text;
      .for-all {
        -webkit-text-stroke-color: @text !important;
      }

      &::before {
        background:
          radial-gradient(
            180% 80% at 0% 100%,
            @text 0%,
            @blue 25%,
            fade(@mauve, 90%) 56%,
            fade(@mauve, 50%) 79%,
            transparent 100%
          ),
          @crust;
      }
    }

    /* Sub progress bar */

    .progress-circle {
      #progress {
        stroke: @accent;
      }
    }

    .subgrid .badge {
      color: @subtext0 !important;
    }

    /* Subscribe gradients */
    .gradient {
      color: @text !important;

      &.g1 {
        background:
          radial-gradient(
            150% 180% at 50% 180%,
            @peach,
            @yellow 1%,
            @yellow 25%,
            @mantle 75%
          ),
          var(--secondary) !important;
      }

      &.g2 {
        background:
          radial-gradient(
            150% 180% at 50% 180%,
            @text,
            @red 1%,
            @red 25%,
            @mantle 75%
          ),
          var(--secondary) !important;
      }

      &.g3 {
        background:
          radial-gradient(
            150% 180% at 50% 180%,
            @peach,
            @pink 1%,
            @mauve 25%,
            @mantle 75%
          ),
          var(--secondary) !important;
      }

      &.g5 {
        background:
          radial-gradient(
            150% 180% at 50% 180%,
            @peach,
            @sapphire 1%,
            @sapphire 25%,
            @mantle 75%
          ),
          var(--secondary) !important;
      }
    }

    /* Home page glow */
    .weird-smiley::before,
    .feature .background {
      background-image: radial-gradient(
        circle at bottom,
        fade(@mauve, 20%),
        fade(@sapphire, 20%)
      ) !important;
    }

    .banner {
      color: @base;

      &[style="--gradient-color: #9227cf"] {
        --gradient-color: @mauve !important;
      }
      &[style="--gradient-color: #27cfb1"] {
        --gradient-color: @teal !important;
      }
      &[style="--gradient-color: #ff11bc"] {
        --gradient-color: @red !important;
      }

      &::before {
        background:
          radial-gradient(
            100% 100% at 50% 0%,
            @text 0%,
            var(--gradient-color) 33%,
            @mauve 64%,
            fade(@mauve, 50%) 80%,
            @mantle 100%
          ),
          var(--bg-medium) !important;
      }
    }

    /* Sub badge progress bar */

    progress[value].bar {
      &::-webkit-progress-bar,
      &::-moz-progress-bar {
        background: @accent !important;
      }
    }
  }
}
@-moz-document domain("twitch.tv") {
  .tw-root--theme-dark {
    #catppuccin(@darkFlavor);
  }
  .tw-root--theme-light {
    #catppuccin(@lightFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();

    --seventv-text-color-normal: @text;
    --seventv-text-color-secondary: @subtext0;

    --seventv-border-transparent-1: @surface0;
    --seventv-background-shade-1: @base;
    --seventv-background-shade-2: @mantle;
    --seventv-background-shade-3: @crust;
    --seventv-background-transparent-1: @base;
    --seventv-background-transparent-2: @mantle;
    --seventv-background-transparent-3: @mantle;
    --seventv-highlight-neutral-1: @surface0;
    --seventv-input-background: @mantle;
    --seventv-input-border: @surface0;
    --seventv-subscriber-color: @yellow;

    --seventv-highlight-color: @accent;
    --seventv-highlight-dim-color: fade(@accent, 20%);

    --seventv-primary: @accent;
    --seventv-accent: @green;
    --seventv-warning: @peach;
    --seventv-muted: @subtext0;

    .seventv-transparent {
      --seventv-border-transparent-1: fade(@surface0, 77%);
      --seventv-background-transparent-1: fade(@base, 77%);
      --seventv-background-transparent-2: fade(@mantle, 59%);
      --seventv-background-transparent-3: fade(@mantle, 71%);
    }

    .seventv-announce-message-container {
      .announce-header {
        background-color: @crust;
      }
      .announce-message {
        background-color: @base;
      }
    }

    .grabbable-inner, .grabbable-outer {
      --color-border-input: @subtext0;
    }

    .seventv-user-message {
      /* First time chatter */
      &[style*="--seventv-highlight-color: #c832c8"] {
        --seventv-highlight-color: @mauve !important;
        --seventv-highlight-dim-color: fade(@mauve, 10%) !important;
      }
      /* Mention */
      &[style*="--seventv-highlight-color: #e13232"] {
        --seventv-highlight-color: @red !important;
        --seventv-highlight-dim-color: fade(@red, 10%) !important;
      }
      /* Blocked */
      &[style*="--seventv-highlight-color: #9488855A"] {
        --seventv-highlight-color: @surface0 !important;
      }
      /* Raider */
      &[style*="--seventv-highlight-color: #6dd126"] {
        --seventv-highlight-color: @green !important;
        --seventv-highlight-dim-color: fade(@green, 10%) !important;
      }
      /* Returning chatter */
      &[style*="--seventv-highlight-color: #3296e6"] {
        --seventv-highlight-color: @blue !important;
        --seventv-highlight-dim-color: fade(@blue, 10%) !important;
      }
    }

    .seventv-chat-message-container:hover .seventv-chat-message-background {
      background-color: @surface0;
    }

    .seventv-sub-message-container, .seventv-reward-message-container {
      background-color: @base;
    }

    .seventv-settings-category {
      .seventv-settings-category-dropdown .seventv-settings-subcategory {
        &:hover {
          background-color: @base !important;
        }
        &.intersect {
          background-color: @surface0 !important;
        }
      }

      .settings-category-header {
        &:hover, &:focus-within {
          background-color: @base;
        }
      }
    }

    .seventv-settings-category[in-view="true"] > .settings-category-header {
      background-color: @surface0;
    }

    .paint-tool-home {
      h6[style="color: red;"] {
        color: @peach !important;
      }
    }

    section[timeline-id="LIVE"] {
      label, div[selector="date-boundary"] {
        color: @red;
        border-color: @red;
      }
    }

    .seventv-emote-container[zero-width="true"] {
      border-color: @yellow;
    }

    .scope-labels {
      .label-global {
        color: @green;
      }
      .label-sub-feature {
        color: @yellow;
      }
    }

    [style*="rgb(255, 255, 255)"] .seventv-chat-user-username span {
      color: @text !important;
    }

    .seventv-chat-mod-buttons {
      color: @subtext0;

      svg:hover {
        color: @text;
      }
    }
  }
}

/* ==UserStyle==
@name Syncthing Catppuccin
@namespace github.com/catppuccin/userstyles/styles/syncthing
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/syncthing
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/syncthing/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Asyncthing
@description Soothing pastel theme for Syncthing
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]

@var text urls "URL(s) for Syncthing" "127\.0\.0\.1\:8384,0\.0\.0\.0\:8384,localhost\:8384"
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

/*
  `replace(<stuff> ," ", "", "g")` is here to remove extra spaces (if any)
*/

@-moz-document regexp(
    replace(replace(%("https?://(%s)/.*", @urls), ",", "|", "g"), " ", "", "g")
  ) {
  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  .light-theme {
    #catppuccin(@lightFlavor);
  }
  .dark-theme {
    #catppuccin(@darkFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    body {
      color: @text !important;
      background-color: @base !important;
    }

    a {
      color: @accent;
    }

    .nav-tabs > li.active > a:hover,
    .nav-tabs > li.active > a {
      color: @accent !important;
    }

    /* navbar */
    .navbar {
      background-color: @mantle !important;
      border-color: @mantle !important;
    }

    .navbar-text,
    .dropdown > a,
    .dropdown-menu > li > a,
    .hidden-xs > a,
    .navbar-link {
      color: @text !important;
    }

    .dropdown-menu {
      border-color: @surface1 !important;
      background-color: @mantle !important;
    }

    .dropdown-menu > li > a:hover,
    .dropdown-menu > li > a:focus {
      color: @text !important;
      background-color: @surface0 !important;
    }

    .open > .dropdown-toggle,
    .dropdown-toggle:hover {
      border-color: @surface1 !important;
      background-color: @surface0 !important;
    }

    .divider {
      background-color: @surface1 !important;
    }

    li.hidden-xs:hover,
    .navbar-link:hover,
    .navbar-link:focus {
      border-color: @surface1 !important;
      background-color: @surface0 !important;
    }

    .dropdown-menu > .active > a {
      color: @base !important;
      background-color: @accent !important;
    }

    /* main panel */
    .panel {
      background-color: @base !important;
    }

    .panel-default {
      border-color: @surface0 !important;
    }

    .panel-default > .panel-heading {
      color: @text !important;
      border-color: @surface0 !important;
      background-color: @surface0 !important;
    }

    .panel-footer {
      background-color: @base !important;
    }

    .table-striped > tbody > tr {
      border-top-color: @surface0 !important;
    }

    .table-striped > tbody > tr:nth-of-type(odd) {
      background-color: @base !important;
    }

    .panel-group .panel-heading + .panel-collapse > .panel-body,
    .panel-group .panel-heading + .panel-collapse > .list-group {
      border-top-color: @base !important;
    }

    .identicon > rect {
      fill: @text !important;
    }

    /* buttons */
    .btn-default {
      color: @text !important;
      background-color: transparent !important;
      border-color: @surface0 !important;
    }

    .btn-default:hover,
    .btn-default:focus,
    .btn-default.focus {
      color: @text !important;
      background-color: @surface0 !important;
    }

    .btn-primary {
      background-color: @accent !important;
      color: @base;
    }

    .btn-primary:hover,
    .btn-primary:focus,
    .btn-primary.focus {
      background-color: fade(@accent, 90%) !important;
    }

    .btn-warning {
      background-color: @yellow !important;
      color: @base;
    }

    .btn-warning:hover,
    .btn-warning:focus,
    .btn-warning.focus {
      background-color: fade(@yellow, 90%) !important;
    }

    .btn-danger {
      background-color: @red !important;
      color: @base;
    }

    .btn-danger:hover,
    .btn-danger:focus,
    .btn-danger.focus {
      background-color: fade(@red, 90%) !important;
    }

    /* modal dialogs */
    .modal-header {
      border-color: @surface0 !important;
      background-color: @mantle;
    }

    .modal-content {
      border-color: @surface0 !important;
      background-color: @mantle !important;
    }

    .modal-footer {
      border-color: @surface0 !important;
      background-color: @mantle !important;
    }

    .alert-warning {
      background-color: @yellow !important;
      color: @base !important;
    }

    .alert-danger {
      background-color: @red !important;
      color: @base !important;
    }

    .help-block {
      color: @text !important;
    }

    .form-control {
      color: @text !important;
      border-color: @surface0 !important;
      background-color: @base !important;
    }

    code.ng-binding {
      color: @mauve !important;
      background-color: @mantle !important;
    }

    .well,
    .form-control[readonly="readonly"] {
      /* read-only fields */
      color: @subtext0 !important;
      border-color: @subtext0 !important;
      background-color: @mantle !important;
    }

    /* buttons for pagination */
    .pagination > li > a,
    .pagination > li > span {
      background-color: @base !important;
      border-color: @surface0 !important;
    }

    .pagination > li > a:hover,
    .pagination > li > a:focus,
    .pagination > li > a.focus {
      background-color: @surface0 !important;
    }

    /* progress bars */
    .progress-bar {
      background-color: @accent !important;
    }

    .progress-bar-success {
      background-color: @green !important;
    }

    .progress-bar-info {
      background-color: @flamingo !important;
    }

    .progress-bar-warning {
      background-color: @yellow !important;
    }

    .progress-bar-danger {
      background-color: @red !important;
    }

    /* text */
    .text-primary {
      color: @accent !important;
    }

    .text-success {
      color: @green !important;
    }

    .text-info {
      color: @flamingo !important;
    }

    .text-warning {
      color: @yellow !important;
    }

    .text-danger {
      color: @red !important;
    }
  }
}

/* ==UserStyle==
@name Zen Browser Docs Catppuccin
@namespace github.com/catppuccin/userstyles/styles/zen-browser-docs
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/zen-browser-docs
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/zen-browser-docs/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Azen-browser-docs
@description Soothing pastel theme for Zen Browser Docs
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("zen-browser.app") {
  :root[data-theme="light"],
  .light {
    #catppuccin(@lightFlavor);
  }

  :root[data-theme="dark"],
  .dark {
    #catppuccin(@darkFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    --zen-paper: @mantle;
    --zen-dark: @subtext1;
    --zen-subtle: @surface0;

    --color-fd-background: @mantle;
    --color-fd-popover: @mantle;
    --color-fd-secondary: @base;
    --color-fd-accent: @surface0;
    --color-fd-card: @crust;
    --color-fd-border: @surface0;
    --color-fd-ring: @overlay0;

    --color-fd-primary: @accent;
    --color-fd-muted: fade(@subtext1, 5%);

    --color-fd-foreground: @subtext1;
    --color-fd-accent-foreground: @subtext1;
    --color-fd-card-foreground: @subtext1;
    --color-fd-primary-foreground: @subtext1;
    --color-fd-secondary-foreground: @subtext1;
    --color-fd-popover-foreground: @subtext1;
    --color-fd-muted-foreground: @subtext1;

    --color-blue-500: @blue;
    --color-red-500: @red;
    --color-orange-500: @peach;

    .text-coral,
    .zen-link,
    .extra a,
    .text-\[\#fe846b\],
    .text-\[\#f7a74b\],
    .text-\[\#f76f53\],
    .hover\:text-coral:hover {
      color: @accent;
    }

    .text-\[\#e3401f\],
    .dark\:text-\[\#D02908\] {
      color: @red;
    }

    .hover\:text-fd-accent-foreground:hover {
      color: @text;
    }

    .dark\:text-white\/50 {
      color: @subtext0;
    }

    #nd-sidebar {
      --color-fd-secondary: @base;
      --color-fd-muted: fade(@subtext1, 5%);
      --color-fd-muted-foreground: @text;
    }

    img[src="/icon.svg"] {
      @svg: escape(
        '<svg viewBox="0 0 64 64" fill="none" xmlns="http://www.w3.org/2000/svg"><path fill-rule="evenodd" clip-rule="evenodd" d="M32 44.308c6.797 0 12.308-5.51 12.308-12.308 0-6.797-5.51-12.308-12.308-12.308-6.797 0-12.308 5.51-12.308 12.308 0 6.797 5.51 12.308 12.308 12.308M41.846 32c0 5.438-4.408 9.846-9.846 9.846S22.154 37.438 22.154 32s4.408-9.846 9.846-9.846 9.846 4.408 9.846 9.846" fill="@{accent}"/><path fill-rule="evenodd" clip-rule="evenodd" d="M53.333 32c0 11.782-9.55 21.333-21.333 21.333S10.667 43.783 10.667 32 20.217 10.667 32 10.667 53.333 20.217 53.333 32M32 49.23c9.516 0 17.23-7.714 17.23-17.23S41.517 14.77 32 14.77 14.77 22.483 14.77 32 22.483 49.23 32 49.23" fill="@{accent}"/><path fill-rule="evenodd" clip-rule="evenodd" d="M64 32c0 17.673-14.327 32-32 32S0 49.673 0 32 14.327 0 32 0s32 14.327 32 32M32 58.256c14.501 0 26.256-11.755 26.256-26.256S46.501 5.744 32 5.744 5.744 17.499 5.744 32 17.499 58.256 32 58.256" fill="@{accent}"/></svg>'
      );
      content: url("data:image/svg+xml,@{svg}");
    }
  }
}
